import styles from './AzMap.module.css';

// The A to Z map, drawn from data generated by protocol/az-map/build.mjs in the
// knowledge repository. Server component, no client script.
//
// On the public site a locked node arrives as a title and a length only. The
// blurred lines under it are filler made here from that length: the real text
// is not in this repository and not on the page.

export type AzKind = 'step' | 'decision' | 'question' | 'stop' | 'optional' | 'outcome';

export interface AzNode {
  id: string;
  kind: AzKind;
  title: string;
  body?: string;
  locked?: boolean;
  len?: number;
  branch?: string;
  jump?: { label: string; toSection: number; toTitle: string };
}

export interface AzRow {
  main: AzNode;
  side: AzNode[];
  asks: AzNode[];
}

export interface AzSection {
  n: number;
  title: string;
  rows: AzRow[];
}

export interface AzMapData {
  title: string;
  subtitle: string;
  sections: AzSection[];
}

export interface AzLock {
  href: string;
  /** First line of the call-out, e.g. "Members see the full map". */
  lead: string;
  /** Second line, the action, e.g. "Join for $29/month". */
  action: string;
}

const EYEBROW: Record<AzKind, string> = {
  step: 'Step',
  decision: 'Decision',
  question: 'People ask',
  stop: 'Stop or detour',
  optional: 'Optional, per case',
  outcome: 'Then',
};

const KEY: { kind: AzKind; label: string }[] = [
  { kind: 'step', label: 'Step' },
  { kind: 'decision', label: 'Decision' },
  { kind: 'question', label: 'Question people ask' },
  { kind: 'stop', label: 'Stop or detour' },
  { kind: 'optional', label: 'Optional, per case' },
];

const FILLER_WORDS = [
  'the', 'body', 'before', 'after', 'days', 'when', 'only', 'with', 'first', 'then',
  'signs', 'case', 'rest', 'from', 'each', 'week', 'until', 'plan', 'read', 'slow',
  'warm', 'keep', 'must', 'never', 'because', 'comes', 'next', 'start', 'over', 'still',
];

/** Deterministic nonsense of roughly `len` characters, seeded by the node id. */
function filler(len: number, id: string): string {
  let seed = 7;
  for (const ch of id) seed = (seed * 31 + ch.charCodeAt(0)) % 2147483647;
  const out: string[] = [];
  let size = 0;
  while (size < len) {
    seed = (seed * 48271) % 2147483647;
    const word = FILLER_WORDS[seed % FILLER_WORDS.length];
    out.push(word);
    size += word.length + 1;
  }
  return out.join(' ');
}

export const sectionAnchor = (n: number) => `step-${n}`;

function Node({ node, lock }: { node: AzNode; lock?: AzLock }) {
  const eyebrow =
    node.branch && (node.kind === 'stop' || node.kind === 'outcome')
      ? `If ${node.branch}`
      : EYEBROW[node.kind];
  return (
    <div className={`${styles.node} ${styles[node.kind]}`}>
      <span className={styles.eyebrow}>{eyebrow}</span>
      <h3 className={styles.nodeTitle}>{node.title}</h3>
      {node.body ? <p className={styles.body}>{node.body}</p> : null}
      {node.locked && lock ? (
        <a
          className={styles.locked}
          href={lock.href}
          aria-label={`Members only: ${node.title}. ${lock.action}.`}
        >
          <span className={styles.filler} aria-hidden="true" data-nosnippet>
            {filler(node.len ?? 80, node.id)}
          </span>
          <span className={styles.lockTag} aria-hidden="true">
            Members
          </span>
          <span className={styles.callout} aria-hidden="true">
            <span className={styles.calloutLead}>{lock.lead}</span>
            <span className={styles.calloutAction}>{lock.action}</span>
          </span>
        </a>
      ) : null}
      {node.jump ? (
        <a className={styles.jump} href={`#${sectionAnchor(node.jump.toSection)}`}>
          {node.jump.label}: go to {node.jump.toSection} · {node.jump.toTitle}
        </a>
      ) : null}
    </div>
  );
}

export function AzMap({ map, lock }: { map: AzMapData; lock?: AzLock }) {
  return (
    <div className={styles.map}>
      <ul className={styles.key} aria-label="Key">
        {KEY.map((k) => (
          <li key={k.kind} className={`${styles.keyItem} ${styles[k.kind]}`}>
            <span
              className={`${styles.keyDot} ${k.kind === 'decision' ? styles.keyDotDecision : ''}`}
              aria-hidden="true"
            />
            {k.label}
          </li>
        ))}
      </ul>

      {map.sections.map((section) => (
        <section
          key={section.n}
          id={sectionAnchor(section.n)}
          className={styles.section}
          aria-labelledby={`${sectionAnchor(section.n)}-title`}
        >
          <div className={styles.sectionHead}>
            <span className={styles.sectionNum} aria-hidden="true">
              {section.n}
            </span>
            <h2 id={`${sectionAnchor(section.n)}-title`} className={styles.sectionTitle}>
              {section.title}
            </h2>
          </div>
          <ol className={styles.rows}>
            {section.rows.map((row) => (
              <li key={row.main.id} className={styles.row}>
                <div className={styles.main}>
                  <Node node={row.main} lock={lock} />
                </div>
                {row.side.length > 0 ? (
                  <div className={styles.side}>
                    {row.side.map((n) => (
                      <Node key={n.id} node={n} lock={lock} />
                    ))}
                  </div>
                ) : null}
                {row.asks.length > 0 ? (
                  <div className={styles.asks}>
                    {row.asks.map((n) => (
                      <Node key={n.id} node={n} lock={lock} />
                    ))}
                  </div>
                ) : null}
              </li>
            ))}
          </ol>
        </section>
      ))}
    </div>
  );
}
